type ChangeEntryItem struct {
	RecordID      int64
	RecordedAt    string
	EntryID       int64
	Entry         ChangeEntry
	PublicID      string
	Environment   string
	Version       string
	BatchID       string
	GateStatus    string
	RollbackPoint string
}

